#!/bin/sh
# Generates the media container test fixtures. Runs inside the media image (it needs ffmpeg with libx265 and zscale,
# and node for the download), on a Linux x86_64 Docker host:
#
#   docker run --rm --user "$(id -u):$(id -g)" \
#     -v "$PWD/scripts:/scripts:ro" -v "$PWD/test/fixtures/media:/out" \
#     immich-cf-media-p3a sh /scripts/media-fixtures.sh /out
#
# big.jpg (over 20 MB) is generated by the test itself and never stored here.
set -eu

OUT="${1:-test/fixtures/media}"
mkdir -p "$OUT"
cd "$OUT"

FF="ffmpeg -hide_banner -loglevel error -y"

# 10-bit HEVC tagged PQ/BT.2020, iPhone-style QuickTime metadata, moov at the end (no faststart).
# The SDR test pattern is converted to PQ (100 nit white) so the file looks like real HDR to a decoder. Temporal noise
# and 2 Mbit/s over 10 s (about 2.5 MB) keep the per-request fixed costs (header probe, one GOP) a small share of the
# file, so the Range test measures something; keyframes every second like a phone recording.
$FF -f lavfi -i "testsrc2=size=1280x720:rate=30:duration=10" \
  -vf "noise=alls=12:allf=t,zscale=tin=bt709:min=bt709:pin=bt709:rin=tv:t=smpte2084:m=bt2020nc:p=bt2020:r=tv:npl=100,format=yuv420p10le" \
  -c:v libx265 -pix_fmt yuv420p10le -preset fast -b:v 2M \
  -x265-params "log-level=error:keyint=30:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc" \
  -color_primaries bt2020 -color_trc smpte2084 -colorspace bt2020nc -tag:v hvc1 \
  -metadata:g com.apple.quicktime.creationdate=2024-07-14T18:03:12+0300 \
  -metadata:g com.apple.quicktime.location.ISO6709=+34.6823+033.0464+012.000/ \
  -movflags use_metadata_tags \
  hdr-hevc-moov-end.mov

# H.264 stored landscape with a 90 degree display matrix (portrait phone video).
$FF -display_rotation 90 -f lavfi -i "testsrc2=size=1280x720:rate=30:duration=2" \
  -c:v libx264 -pix_fmt yuv420p -preset fast -crf 28 rotated.mov

# No metadata at all.
$FF -f lavfi -i "testsrc2=size=640x360:rate=30:duration=2" \
  -c:v libx264 -pix_fmt yuv420p -preset fast -crf 28 -map_metadata -1 -fflags +bitexact plain.mp4

# CC0 DNG from raw.pixls.us (Adobe DNG Converter, Canon EOS 5D Mark III, lossy JPEG DNG, 3960x2640, 2.37 MB).
# Source and licence in SOURCES.md.
DNG=canon-5d3-adobe-lossy.dng
DNG_URL='https://raw.pixls.us/getfile.php/1033/nice/Adobe%20DNG%20Converter%20-%20Canon%20EOS%205D%20Mark%20III%20-%20Lossy%20JPEG%20compression%2C%20rgb%20%283%3A2%29.DNG'
if [ ! -s "$DNG" ]; then
  node -e '
    const [url, out] = process.argv.slice(1);
    const r = await fetch(url);
    if (!r.ok) { console.error(`download failed: ${r.status}`); process.exit(1); }
    (await import("node:fs")).writeFileSync(out, Buffer.from(await r.arrayBuffer()));
  ' --input-type=module "$DNG_URL" "$DNG"
fi
echo "b22f1e36331f679abb8b13e433b9bbde3988723adf10fee7aa0dda6381016a98  $DNG" | sha256sum -c -

# CC0 DNG with no embedded preview (Magic Lantern MLV frame, Canon EOS 5D Mark III, 1920x818, 1.5 MB): exercises the
# dcraw_emu decode path.
DNG2=canon-5d3-mlv-nopreview.dng
DNG2_URL='https://raw.pixls.us/getfile.php/2204/nice/Canon%20-%20EOS%205D%20Mark%20III%20-%2014bit%2014bit%20%282.3471882640587%29.dng'
if [ ! -s "$DNG2" ]; then
  node -e '
    const [url, out] = process.argv.slice(1);
    const r = await fetch(url);
    if (!r.ok) { console.error(`download failed: ${r.status}`); process.exit(1); }
    (await import("node:fs")).writeFileSync(out, Buffer.from(await r.arrayBuffer()));
  ' --input-type=module "$DNG2_URL" "$DNG2"
fi
echo "1d77dcc6cdb839b10c1948f0b4471984ab48cf15e973fb77520584cee72b603e  $DNG2" | sha256sum -c -

ls -l
